// ======================================
// 1. REFERÊNCIAS DO HTML
// ======================================

const formPessoa = document.getElementById("formPessoa");

const inputNome = document.getElementById("nome");
const inputIdade = document.getElementById("idade");
const inputAltura = document.getElementById("altura");
const inputPeso = document.getElementById("peso");

const listaPessoas = document.getElementById("listaPessoas");
const mensagemDeErro = document.getElementById("erro");
const contador = document.getElementById("contador");


// ======================================
// 2. VARIÁVEIS DO SISTEMA
// ======================================

const chavePessoas = "pessoas";

let pessoas = [];
let proximoId = 1;


// ======================================
// 3. FUNÇÃO CALCULAR IMC
// ======================================

function calcularIMC(peso, altura) {

    return peso / (altura * altura);

    }


    // ======================================
    // 4. FUNÇÃO CLASSIFICAR IMC
    // ======================================

    function classificarIMC(imc) {

        if (imc < 18.5) {

                return {
                            texto: "Abaixo do peso",
                                        classe: "baixo-peso"
                                                };

                                                    }

                                                        if (imc < 25) {

                                                                return {
                                                                            texto: "Peso normal",
                                                                                        classe: "normal"
                                                                                                };

                                                                                                    }

                                                                                                        if (imc < 30) {

                                                                                                                return {
                                                                                                                            texto: "Sobrepeso",
                                                                                                                                        classe: "sobrepeso"
                                                                                                                                                };

                                                                                                                                                    }

                                                                                                                                                        return {
                                                                                                                                                                texto: "Obesidade",
                                                                                                                                                                        classe: "obesidade"
                                                                                                                                                                            };

                                                                                                                                                                            }


                                                                                                                                                                            // ======================================
                                                                                                                                                                            // 5. FUNÇÃO FORMATAR VALORES
                                                                                                                                                                            // ======================================

                                                                                                                                                                            function formatar(valor, casas) {

                                                                                                                                                                                return valor.toFixed(casas);

                                                                                                                                                                                }


                                                                                                                                                                                // ======================================
                                                                                                                                                                                // 6. CRIAR LINHA DA TABELA
                                                                                                                                                                                // ======================================

                                                                                                                                                                                function criarLinha(pessoa) {

                                                                                                                                                                                    const linha = document.createElement("tr");

                                                                                                                                                                                        const imc = calcularIMC(pessoa.peso, pessoa.altura);

                                                                                                                                                                                            const classificacao = classificarIMC(imc);

                                                                                                                                                                                                function criarCelula(texto) {

                                                                                                                                                                                                        const td = document.createElement("td");

                                                                                                                                                                                                                td.textContent = texto;

                                                                                                                                                                                                                        linha.appendChild(td);

                                                                                                                                                                                                                                return td;

                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                        criarCelula(pessoa.id);

                                                                                                                                                                                                                                            criarCelula(pessoa.nome);

                                                                                                                                                                                                                                                criarCelula(pessoa.idade);

                                                                                                                                                                                                                                                    criarCelula(formatar(pessoa.altura, 2) + " m");

                                                                                                                                                                                                                                                        criarCelula(formatar(pessoa.peso, 1) + " kg");

                                                                                                                                                                                                                                                            criarCelula(formatar(imc, 1));

                                                                                                                                                                                                                                                                const tdClassificacao = document.createElement("td");

                                                                                                                                                                                                                                                                    const selo = document.createElement("span");

                                                                                                                                                                                                                                                                        selo.classList.add("selo", classificacao.classe);

                                                                                                                                                                                                                                                                            selo.textContent = classificacao.texto;

                                                                                                                                                                                                                                                                                tdClassificacao.appendChild(selo);

                                                                                                                                                                                                                                                                                    linha.appendChild(tdClassificacao);

                                                                                                                                                                                                                                                                                        // Botão apagar

                                                                                                                                                                                                                                                                                            const tdAcao = document.createElement("td");

                                                                                                                                                                                                                                                                                                const botaoApagar = document.createElement("button");

                                                                                                                                                                                                                                                                                                    botaoApagar.textContent = "Apagar";

                                                                                                                                                                                                                                                                                                        botaoApagar.classList.add("btn-apagar");

                                                                                                                                                                                                                                                                                                            botaoApagar.addEventListener("click", function() {

                                                                                                                                                                                                                                                                                                                    apagarPessoa(pessoa.id);

                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                            tdAcao.appendChild(botaoApagar);

                                                                                                                                                                                                                                                                                                                                linha.appendChild(tdAcao);

                                                                                                                                                                                                                                                                                                                                    return linha;

                                                                                                                                                                                                                                                                                                                                    }


                                                                                                                                                                                                                                                                                                                                    // ======================================
                                                                                                                                                                                                                                                                                                                                    // 7. RENDERIZAR TABELA
                                                                                                                                                                                                                                                                                                                                    // ======================================

                                                                                                                                                                                                                                                                                                                                    function render() {

                                                                                                                                                                                                                                                                                                                                        listaPessoas.innerHTML = "";

                                                                                                                                                                                                                                                                                                                                            pessoas.forEach(function(pessoa) {

                                                                                                                                                                                                                                                                                                                                                    const linha = criarLinha(pessoa);

                                                                                                                                                                                                                                                                                                                                                            listaPessoas.appendChild(linha);

                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                    contador.textContent =
                                                                                                                                                                                                                                                                                                                                                                            "Total de pacientes: " + pessoas.length;

                                                                                                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                                                                                                            // ======================================
                                                                                                                                                                                                                                                                                                                                                                            // 8. LER FORMULÁRIO
                                                                                                                                                                                                                                                                                                                                                                            // ======================================

                                                                                                                                                                                                                                                                                                                                                                            function lerFormulario() {

                                                                                                                                                                                                                                                                                                                                                                                return {

                                                                                                                                                                                                                                                                                                                                                                                        nome: inputNome.value.trim(),

                                                                                                                                                                                                                                                                                                                                                                                                idade: Number(inputIdade.value),

                                                                                                                                                                                                                                                                                                                                                                                                        altura: Number(inputAltura.value),

                                                                                                                                                                                                                                                                                                                                                                                                                peso: Number(inputPeso.value)

                                                                                                                                                                                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                                                                                                                                                                                    }


                                                                                                                                                                                                                                                                                                                                                                                                                    // ======================================
                                                                                                                                                                                                                                                                                                                                                                                                                    // 9. VALIDAR DADOS
                                                                                                                                                                                                                                                                                                                                                                                                                    // ======================================

                                                                                                                                                                                                                                                                                                                                                                                                                    function validarDados(dados) {

                                                                                                                                                                                                                                                                                                                                                                                                                        if (dados.nome.length < 2) {

                                                                                                                                                                                                                                                                                                                                                                                                                                return "Informe um nome com no mínimo duas letras.";

                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                        if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                !Number.isInteger(dados.idade) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                        dados.idade < 1 ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                dados.idade > 120
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return "A idade deve ser um número inteiro entre 1 e 120.";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            !Number.isFinite(dados.altura) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    dados.altura < 0.5 ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            dados.altura > 2.5
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return "A altura deve estar entre 0,50 m e 2,50 m.";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        !Number.isFinite(dados.peso) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                dados.peso < 2 ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        dados.peso > 500
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return "O peso deve estar entre 2 kg e 500 kg.";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return "";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // ======================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // 10. MOSTRAR ERRO
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // ======================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function mostrarErro(mensagem) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mensagemDeErro.textContent = mensagem;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mensagemDeErro.hidden = false;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // ======================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // 11. LIMPAR ERRO
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // ======================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function limparErro() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        mensagemDeErro.textContent = "";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mensagemDeErro.hidden = true;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // ======================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // 12. ADICIONAR PESSOA
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // ======================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function adicionarPessoa(dados) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const pessoa = {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        id: proximoId++,

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                nome: dados.nome,

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        idade: dados.idade,

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                altura: dados.altura,

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        peso: dados.peso

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                pessoas.push(pessoa);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // ======================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // 13. SALVAR NO LOCALSTORAGE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // ======================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function salvar() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    localStorage.setItem(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            chavePessoas,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    JSON.stringify(pessoas)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ======================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 14. CARREGAR PESSOAS SALVAS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ======================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function carregarPessoas() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const dadosSalvos = localStorage.getItem(chavePessoas);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!dadosSalvos) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return [];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                try {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const dados = JSON.parse(dadosSalvos);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!Array.isArray(dados)) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            throw new Error("Os dados não são uma lista.");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return dados.filter(function(pessoa) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return pessoa &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Number.isInteger(pessoa.id) &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pessoa.id > 0 &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        typeof pessoa.nome === "string" &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Number.isInteger(pessoa.idade) &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pessoa.idade >= 1 &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pessoa.idade <= 120 &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Number.isFinite(pessoa.altura) &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pessoa.altura >= 0.5 &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pessoa.altura <= 2.5 &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Number.isFinite(pessoa.peso) &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pessoa.peso >= 2 &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pessoa.peso <= 500;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } catch (erro) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            console.error("Erro ao carregar pessoas:", erro);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return [];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ======================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 15. AJUSTAR CONTADOR DE CÓDIGO
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ======================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function ajustarContadorCodigo() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let maior = 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                pessoas.forEach(function(pessoa) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (pessoa.id > maior) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    maior = pessoa.id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    proximoId = maior + 1;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // ======================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // 16. APAGAR PESSOA
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // ======================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function apagarPessoa(id) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pessoas = pessoas.filter(function(pessoa) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return pessoa.id !== id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        salvar();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            render();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // ======================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // 17. EVENTO DE ENVIO DO FORMULÁRIO
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // ======================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            formPessoa.addEventListener("submit", function(event) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                event.preventDefault();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const dados = lerFormulario();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const erro = validarDados(dados);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (erro !== "") {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mostrarErro(erro);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    limparErro();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        adicionarPessoa(dados);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            salvar();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                render();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    formPessoa.reset();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        inputNome.focus();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ======================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 18. INICIALIZAÇÃO DO SISTEMA
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ======================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pessoas = carregarPessoas();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ajustarContadorCodigo();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        render();